   id=r['case'];task=id in passes;entry={k:r[k] for k in ['case','mode','profile','context_mode','answer','expected','context_sha256','prompt_sha256']}
   entry.update(task_pass=task,strict_pass=task and id not in spec['labels'].split(),episode_error=id in spec['episode'].split(),unsupported_addition=id in spec['unsupported'].split(),spoiler=id in spec['spoiler'].split(),review_note=fails.get(id,'Source-grounded complete answer; labels/order/conditions checked against saved evidence.'))
